// ============================================================
//  🚀 VSA Universal Bridge V5.1 - OFFICIAL SDK (Edge Compatible)
//  التحديث: إصلاح مشكلة الاستيراد في Cloudflare
// ============================================================

// استيراد النسخة المتوافقة مع Edge من مكتبة جوجل الرسمية
import { GoogleGenAI } from "@google/generative-ai";

export default {
    async fetch(request, env) {
        const url = new URL(request.url);
        const path = url.pathname;

        const corsHeaders = {
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type, Authorization, User-Agent',
            'Access-Control-Expose-Headers': '*',
        };

        if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders });

        // 1. مسار Gemini API عبر المكتبة الرسمية
        if (path.startsWith('/gemini')) {
            const apiKey = env.GEMINI_API_KEY;
            if (!apiKey) return errorResponse('GEMINI_API_KEY not set', 500, corsHeaders);

            try {
                const body = await request.json();
                const requestedModel = (body.model || 'gemini-1.5-flash').toLowerCase().trim();

                // تهيئة المكتبة الرسمية
                const genAI = new GoogleGenAI(apiKey);
                const model = genAI.getGenerativeModel({ model: requestedModel });

                // إرسال الطلب (المكتبة تتكفل بالباقي)
                const result = await model.generateContent(body.contents);
                const response = await result.response;
                const text = response.text();

                return new Response(JSON.stringify({
                    candidates: [{ content: { role: "model", parts: [{ text: text }] } }]
                }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

            } catch (e) {
                return errorResponse(`Official SDK Error: ${e.message}`, 400, corsHeaders);
            }
        }

        // مسار البحث كما هو
        if (path === '/search') {
            const query = url.searchParams.get('q');
            if (!query) return errorResponse('Missing query', 400, corsHeaders);
            let combinedResults = "";
            try {
                const gRes = await fetch(`https://www.googleapis.com/customsearch/v1?key=${env.GOOGLE_SEARCH_KEY}&cx=${env.GOOGLE_SEARCH_CX}&q=${encodeURIComponent(query)}&num=5`);
                const gData = await gRes.json();
                if (gData.items) {
                    combinedResults += "🔍 **نتائج البحث:**\n\n";
                    gData.items.forEach((item, i) => { combinedResults += `${i+1}. ${item.title}\n   🔗 ${item.link}\n\n`; });
                }
            } catch (e) {}
            return new Response(JSON.stringify({ success: true, results: combinedResults }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
        }

        return new Response('🚀 VSA Bridge V5.1 Active.', { status: 200, headers: corsHeaders });
    }
};

function errorResponse(message, status, corsHeaders) {
    return new Response(JSON.stringify({ error: message }), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

/**
 * VSA Academy Sovereign Bridge - TRANSPARENT RESILIENCE ENGINE
 * ---------------------------------------------------------------
 * هذا الإصدار يضمن الشفافية المطلقة في ذكر اسم الموديل الذي رد فعلياً.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS'
}

// 🎯 قائمة النماذج السيادية لعام 2026
const MODEL_ROUTES = [
    { key: "gemini-3.7-flash", id: "gemini-3.7-flash" },
    { key: "gemini-3.6-flash", id: "gemini-3.6-flash" },
    { key: "gemini-3.5-flash-lite", id: "gemini-3.5-flash-lite" },
    { key: "gemini-3.5-flash", id: "gemini-3.5-flash" },
    { key: "gemini-3.1-flash-lite", id: "gemini-3.1-flash-lite" },
    { key: "gemini-3-flash-preview", id: "gemini-3-flash-preview" },
    { key: "gemini-2.5-pro", id: "gemini-2.5-pro" },
    { key: "gemini-2.5-flash-lite", id: "gemini-2.5-flash-lite" },
    { key: "gemini-2.5-flash", id: "gemini-2.5-flash" },
    { key: "gemini-omni-1.1-flash", id: "gemini-omni-1.1-flash" },
    { key: "gemini-3.1-flash-lite-image", id: "gemini-3.1-flash-lite-image" },
    { key: "gemini-3-pro-image", id: "gemini-3-pro-image" },
    { key: "gemini-3.1-flash-image", id: "gemini-3.1-flash-image" }
];

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })

  try {
    const requestData = await req.json();
    const { action, model: requestedModel, endpoint, method, body } = requestData;
    const payload = requestData.payload || requestData;

    if (action === 'health_check') {
        return new Response(JSON.stringify({ status: "ok", message: "VSA Bridge 2026 Online" }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    if (action === 'chat') {
      const apiKey = Deno.env.get("GEMINI_API_KEY")

      let rawId = String(requestedModel || "").trim().toLowerCase();

      // العثور على الفهرس المختار لبدء اللوب منه ومن ثم النزول لأسفل
      let startIndex = MODEL_ROUTES.findIndex(r => rawId.includes(r.key));
      if (startIndex === -1) startIndex = 0;

      const allModelIds = [];
      // إضافة النموذج المختار وما يليه في القائمة (حسب طلب المستخدم: يبدأ من تحت النموذج المحدد)
      for (let i = startIndex; i < MODEL_ROUTES.length; i++) {
          allModelIds.push(MODEL_ROUTES[i].id);
      }
      // إذا أردت تدوير اللوب ليعود للبداية في حال فشل الجميع (اختياري)
      for (let i = 0; i < startIndex; i++) {
          allModelIds.push(MODEL_ROUTES[i].id);
      }

      const userPreference = MODEL_ROUTES[startIndex].id;
      let lastError = null;

      for (const modelId of allModelIds) {
          try {
              const fetchWithVersion = async (version) => {
                  const url = `https://generativelanguage.googleapis.com/${version}/models/${modelId}:generateContent?key=${apiKey}`;
                  return await fetch(url, {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify({
                          system_instruction: payload.system_instruction,
                          contents: payload.contents,
                          tools: payload.tools,
                          generation_config: payload.generationConfig || { maxOutputTokens: 4096 }
                      })
                  });
              };

              let response = await fetchWithVersion('v1beta');
              if (response.status === 404) response = await fetchWithVersion('v1');

              const data = await response.json();

              if (!response.ok) {
                  lastError = data.error?.message || "Model Unavailable";
                  continue;
              }

              // ✅ الشفافية: نرسل اسم الموديل الذي نجح فعلياً في المتغير used_model
              return new Response(JSON.stringify({
                  ...data,
                  used_model: modelId,
                  fallback_active: userPreference !== modelId
              }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

          } catch (err) {
              lastError = err.message;
              continue;
          }
      }
      throw new Error(`كافة النماذج المتاحة استهلكت حصتها. آخر خطأ: ${lastError}`);
    }

    if (action === 'github' || action === 'github_search') {
      const githubToken = Deno.env.get("GITHUB_TOKEN")
      let finalEndpoint = endpoint || requestData.endpoint;

      if (action === 'github_search') {
        const repo = Deno.env.get("GITHUB_REPO") || "ahmedwwaw1/my";
        const query = payload.query || requestData.query;
        finalEndpoint = `https://api.github.com/search/code?q=${encodeURIComponent(query)}+repo:${repo}`;
      }

      const res = await fetch(finalEndpoint, {
        method: method || 'GET',
        headers: {
          'Authorization': `Bearer ${githubToken}`,
          'Accept': 'application/vnd.github+json',
          'Content-Type': 'application/json',
        },
        body: body ? JSON.stringify(body) : undefined
      })
      const data = await res.json()
      return new Response(JSON.stringify(data), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    if (action === 'web_search' || action === 'read_url') {
      if (action === 'read_url') {
          const url = payload.url || requestData.url;
          const res = await fetch(url);
          const text = await res.text();
          return new Response(JSON.stringify({ content: text }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
      }

      const query = payload.query || requestData.query;
      const googleKey = Deno.env.get("GOOGLE_SEARCH_KEY");
      const googleCx = Deno.env.get("GOOGLE_CX"); // معرف محرك البحث المخصص
      const tavilyKey = Deno.env.get("TAVILY_API_KEY");

      // 1. المحاولة عبر Google Search API كمحرك أساسي
      if (googleKey && googleCx) {
        try {
          const googleUrl = `https://www.googleapis.com/customsearch/v1?key=${googleKey}&cx=${googleCx}&q=${encodeURIComponent(query)}`;
          const res = await fetch(googleUrl);
          const data = await res.json();
          if (data.items) {
             return new Response(JSON.stringify({
               source: "google",
               results: data.items.map(i => ({ title: i.title, url: i.link, content: i.snippet }))
             }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
          }
        } catch (e) { console.error("Google Search Failed, falling back to Tavily..."); }
      }

      // 2. المحاولة عبر Tavily API كمحرك ثانوي (أو أساسي في حال فشل جوجل)
      if (tavilyKey) {
        try {
          const response = await fetch("https://api.tavily.com/search", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              api_key: tavilyKey,
              query: query,
              search_depth: "advanced",
              include_answer: true,
              max_results: 5
            })
          });
          const data = await response.json();
          return new Response(JSON.stringify({ source: "tavily", ...data }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
        } catch (err) {
          return new Response(JSON.stringify({ error: `All search engines failed: ${err.message}` }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
        }
      }

      return new Response(JSON.stringify({ error: "No Search API keys configured" }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    // استجابة افتراضية في حال لم يتطابق أي إجراء
    return new Response(JSON.stringify({ error: `Action '${action}' not supported by bridge.` }), {
      status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    })

  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500, headers: corsHeaders
    })
  }
})

